寻找最长寻找最短 <pre><code>func findLongest(arr []int) int {
    left, right := 0, 0
    result := 0

    for right &lt; len(arr) {
        // 1. 扩大窗口，加入 arr[right]

        // 2. 不满足条件时，缩小窗口
        for 不满足条件 {
            // 移除 arr[left]
            left++
        }

        // 3. 更新最优结果
        if right - left + 1 &gt; result {
            result = right - left + 1
        }
        right++
    }
    return result
}
</code></pre> <pre><code>func findShortest(arr []int, target int) int {
