tcp_echo_server.go<pre><code>package main

import (
    "bufio"
    "fmt"
    "io"
    "log"
    "net"
)

func echo(conn net.Conn, connId string) {
    defer conn.Close()

    b := make([]byte, 1024)
    for {
        n, err := conn.Read(b[0:])
        if err == io.EOF {
            log.Println("client disconnected.")
            break
        }
        if err != nil {
            log.Println("unexpected error.")
            break
        }
        log.Printf("received %d bytes: %s\n", n, string(b))

        msg := fmt.Sprintf("[%s] echo: %s", connId, b[0:n])
        if _, err = conn.Write([]byte(msg)); err != nil {
            log.Fatalln("unable to write data.")
        }
    }
}

func main() {
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        log.Fatalln("unable to bind to port")
    }
    log.Println("Listening on :8080")

    connId := 0
    for {
        conn, err := listener.Accept()
        if err != nil {
            log.Fatalln("unable to accept connection")
        }
        connId++
        go echo(conn, fmt.Sprintf("conn-%d", connId))
    }
}
</code></pre>

tcp_proxy.go<pre><code>package main

import (
    "io"
    "log"
    "net"
)

func handler(src net.Conn) {
    // 连接目标服务器
    dst, err := net.Dial("tcp", "target-server:20080")
    if err != nil {
        log.Fatalln("Unable to connect to target server")
    }
    defer dst.Close()

    // 双向转发
    go func() {
        // Client -&gt; Target
        if _, err = io.Copy(dst, src); err != nil {
            log.Fatalln(err)
        }
    }()

    // Target -&gt; Client
    if _, err = io.Copy(src, dst); err != nil {
        log.Fatalln(err)
    }
}

func main() {
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        log.Fatalln("Unable to bind to port")
    }
    log.Println("Proxy listening on :8080")

    for {
        conn, err := listener.Accept()
        if err != nil {
            log.Fatalln("Unable to accept connection")
        }
        go handler(conn)
    }
}
</code></pre> <p>注意双向转发</p> <p>必须用两个 goroutine 分别处理两个方向的数据流，否则会阻塞。</p>

