stream.proto<pre><code>syntax = "proto3";

package stream;
option go_package = "stream/proto/v1";

service Greeter {
    // 服务端流：客户端发一个请求，服务端返回多个响应
    rpc GetStream(StreamReqData) returns (stream StreamResData);

    // 客户端流：客户端发多个请求，服务端返回一个响应
    rpc PutStream(stream StreamReqData) returns (StreamResData);

    // 双向流：双方同时收发
    rpc AllStream(stream StreamReqData) returns (stream StreamResData);
}

message StreamReqData {
    string data = 1;
}

message StreamResData {
    string data = 1;
}
</code></pre>

server.go<pre><code>func (s *Server) GetStream(req *stream.StreamReqData, res stream.Greeter_GetStreamServer) error {
    // 先响应一次请求
    err := res.Send(&amp;stream.StreamResData{
        Data: fmt.Sprintf("收到请求: %s", req.Data),
    })
    if err != nil {
        return err
    }

    // 持续推送数据
    for {
        err = res.Send(&amp;stream.StreamResData{
            Data: fmt.Sprintf("服务端推送: %v", time.Now().Unix()),
        })
        if err != nil {
            fmt.Printf("发送失败: %s\n", err)
            break
        }
        time.Sleep(time.Second)
    }
    return nil
}
</code></pre>

