server.go<pre><code>func (s *Server) PutStream(req stream.Greeter_PutStreamServer) error {
    for {
        data, err := req.Recv()
        if err == io.EOF {
            // 客户端发送完毕，返回响应
            return req.SendAndClose(&amp;stream.StreamResData{
                Data: "接收完成",
            })
        }
        if err != nil {
            fmt.Printf("接收错误: %s\n", err)
            break
        }
        fmt.Printf("收到数据: %s\n", data.Data)
    }
    return nil
}
