hedge_ratio.go<pre><code>package main

import "fmt"

// 计算切片的均值
func mean(data []float64) float64 {
    sum := 0.0
    for _, v := range data {
        sum += v
    }
    return sum / float64(len(data))
}

// 计算对冲比率（OLS 线性回归）
// y = alpha + beta * x
// 返回 beta（对冲比率）和 alpha（截距）
func calcHedgeRatio(x, y []float64) (beta, alpha float64) {
    n := len(x)
    if n != len(y) || n == 0 {
        return 0, 0
    }

    meanX := mean(x)
    meanY := mean(y)

    // 计算协方差和方差
    var covariance, variance float64
    for i := 0; i &lt; n; i++ {
        dx := x[i] - meanX
        dy := y[i] - meanY
        covariance += dx * dy  // Σ(x-x̄)(y-ȳ)
        variance += dx * dx    // Σ(x-x̄)²
    }

    // β = Cov(X,Y) / Var(X)
    beta = covariance / variance

    // α = ȳ - β * x̄
    alpha = meanY - beta*meanX

    return beta, alpha
}
</code></pre>

