// History 历史记录管理器
type History struct {
    mementos []*Memento
}

// Push 保存一个备忘录
func (h *History) Push(m *Memento) {
    h.mementos = append(h.mementos, m)
}

// Pop 取出最近的备忘录
func (h *History) Pop() *Memento {
    if len(h.mementos) == 0 {
        fmt.Println("⚠️ 没有可恢复的状态")
        return nil
    }
    // 取出最后一个
    last := h.mementos[len(h.mementos)-1]
    h.mementos = h.mementos[:len(h.mementos)-1]
    return last
}
