import "fmt"

// Cache 缓存，使用可替换的淘汰策略
type Cache struct {
    storage   map[string]string
    strategy  EvictionStrategy
    capacity  int
    maxSize   int
}

// NewCache 创建缓存
func NewCache(maxSize int, strategy EvictionStrategy) *Cache {
    return &amp;Cache{
        storage:  make(map[string]string),
        strategy: strategy,
        maxSize:  maxSize,
    }
}

// SetStrategy 运行时切换策略
func (c *Cache) SetStrategy(strategy EvictionStrategy) {
    c.strategy = strategy
    fmt.Println("🔧 策略已切换")
}

// Add 添加数据
func (c *Cache) Add(key, value string) {
    if c.capacity &gt;= c.maxSize {
        fmt.Printf("⚠️ 缓存已满（%d/%d），触发淘汰...\n", c.capacity, c.maxSize)
        c.strategy.Evict(c)
    }
    c.storage[key] = value
    c.capacity++
    fmt.Printf("✅ 已添加：%s = %s\n", key, value)
}

// Get 获取数据
func (c *Cache) Get(key string) (string, bool) {
    val, ok := c.storage[key]
    return val, ok
}
